package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"reflect"
)

type LogEntry struct {
	Index   int    `json:"index"`
	Command string `json:"command"`
}

type inputEntries []LogEntry

func (e *inputEntries) UnmarshalJSON(data []byte) error {
	var next []LogEntry
	if err := json.Unmarshal(data, &next); err != nil {
		return err
	}
	*e = next
	return nil
}

type AppendRequest struct {
	Term    int          `json:"term"`
	Entries inputEntries `json:"entries"`
}

type inputRequest AppendRequest

type requestShape struct {
	AppendRequest
	Entries inputEntries `json:"entries"`
}

func (r *inputRequest) UnmarshalJSON(data []byte) error {
	var shape requestShape
	if err := json.Unmarshal(data, &shape); err != nil {
		var te *json.UnmarshalTypeError
		if errors.As(err, &te) {
			fixed := *te
			fixed.Field = trimPrefixOnce(fixed.Field, "AppendRequest.")
			if fixed.Type == reflect.TypeOf(requestShape{}) {
				fixed.Type = reflect.TypeOf(inputRequest{})
			}
			return &fixed
		}
		return err
	}
	shape.AppendRequest.Entries = []LogEntry(shape.Entries)
	*r = inputRequest(shape.AppendRequest)
	return nil
}

func trimPrefixOnce(s, p string) string {
	if len(s) >= len(p) && s[:len(p)] == p {
		return s[len(p):]
	}
	return s
}

type inputRequests []AppendRequest

func (r *inputRequests) UnmarshalJSON(data []byte) error {
	var next []inputRequest
	if err := json.Unmarshal(data, &next); err != nil {
		return err
	}
	reqs := make([]AppendRequest, len(next))
	for i := range next {
		reqs[i] = AppendRequest(next[i])
	}
	*r = reqs
	return nil
}

type inputLog []LogEntry

func (l *inputLog) UnmarshalJSON(data []byte) error {
	var next []LogEntry
	if err := json.Unmarshal(data, &next); err != nil {
		return err
	}
	*l = next
	return nil
}

type In struct {
	Log      inputLog      `json:"log"`
	Requests inputRequests `json:"requests"`
}

func main() {
	cases := []string{
		`{"requests":[{"term":1,"entries":[{"index":1,"command":123}]}]}`,
		`{"log":[{"index":1,"command":123}]}`,
	}
	for _, c := range cases {
		var in In
		err := json.Unmarshal([]byte(c), &in)
		fmt.Printf("err: %v\n", err)
	}
}
