// replicateInputEntry 是读取阶段的日志条目：以库类型 mevwatch.LogEntry 为底层
// 类型另行定义，只为挂载输入特有的 command 解码规则。读完后整个值可直接转换回
// mevwatch.LogEntry，无须逐字段搬运。
type replicateInputEntry mevwatch.LogEntry

// entryUnmarshalShape 是单个日志条目的解码形状。command 故意不落在字符串字段
// 上：第一遍 token 扫描已经判定最后一次 command 出现是否为 null，这里只需要
// index/term 走普通解码，command 解进 RawMessage 丢弃——非字符串/非 null 的
// 任一次出现都由这次解码按既有类型错误拒绝，重复出现由最后一次 RawMessage
// 承载。它只是 UnmarshalJSON 内的局部形状，不构成第二套条目字段。
type entryUnmarshalShape struct {
	Index   int             `json:"index"`
	Term    int             `json:"term"`
	Command json.RawMessage `json:"command"`
}

// UnmarshalJSON 解码一个日志条目，并对 command 施加“同一对象内可重复、最后
// 一次出现决定内容”的规则：
//
//   - 任一次出现（含只改变字段名大小写的写法）为数字、布尔、对象或数组时，
//     都是输入类型错误；后面的合法字符串不能掩盖这次错误。整份输入按既有
//     JSON 类型错误拒绝（退出码 1、标准错误保留 replicate: 前缀）。
//   - 最后一次出现是字符串时按原文保留；是 null 时为空字符串，与单独给出
//     command:null 或省略 command 的结果一致；先 null 后字符串时采用后面的
//     字符串。
//
// 实现上分两遍：第一遍只扫描 token 流，保留键的每一次出现，判定最后一个
// command 是否为 null（map 解码只会留下最后一次出现，无法区分 null 与字符串
// 的先后）；第二遍按普通规则解码 index/term 与 command——后者天然拒绝每一次
// 非字符串/非 null 出现，并在最后一次是字符串时给出原文。第一遍发现最后值为
// null 时，command 直接取空串，跳过第二遍对 command 的解码，避免 encoding/json
// 把 null 静默当成零值时“先字符串后 null 仍保留字符串”的下标覆盖问题。
func (e *replicateInputEntry) UnmarshalJSON(data []byte) error {
	lastNull := lastCommandIsNull(data)

	var shape entryUnmarshalShape
	if !lastNull {
		if err := json.Unmarshal(data, &shape); err != nil {
			return normalizeEntryJSONError(err)
		}
		*e = replicateInputEntry{Index: shape.Index, Term: shape.Term, Command: string(shape.Command.decodedString())}
		return nil
	}

	// 最后一次 command 为 null：command 固定为空串，只解码 index/term。仍解
	// command 到 RawMessage（不进字符串字段），因此前面非 null/非字符串的出现
	// 不会在这里被类型化；这类出现若存在，已由下面的 commandRawShape 二次
	// 校验处理。
	var onlyFields struct {
		Index int `json:"index"`
		Term  int `json:"term"`
	}
	if err := json.Unmarshal(data, &onlyFields); err != nil {
		return normalizeEntryJSONError(err)
	}
	// 最后值虽为 null，前面仍可能出现数字等非法类型：null 会让整体形状解码
	// 跳过类型校验，因此单独确认每一次 command 出现都只能是字符串或 null。
	if err := rejectNonStringCommand(data); err != nil {
		return err
	}
	*e = replicateInputEntry{Index: onlyFields.Index, Term: onlyFields.Term, Command: ""}
	return nil
}

// commandRawMessage 上的 decodedString 返回一次普通解码后字符串 command 的
// 原文。entryUnmarshalShape.Command 是该字段最后一次出现的原始字面量；这里
// 只在“最后出现不是 null”的分支使用，故必为带引号的 JSON 字符串。
func (c json.RawMessage) decodedString() string {
	if len(c) == 0 {
		return "" // 省略 command：空字符串
	}
	var s string
	if err := json.Unmarshal(c, &s); err != nil {
		return "" // 不会发生：类型错误已在 UnmarshalJSON 中被拒绝
	}
	return s
}

// lastCommandIsNull 扫描一个日志条目对象的 token 流，报告按输入顺序最后一次
// 出现的 command（键名大小写不敏感，与 encoding/json 的字段识别一致）是否为
// null。没有 command 出现、条目不是对象或 JSON 无法解析时返回 false——这些
// 情况交给随后的普通类型化解码产出既有结果或错误。token 流保留重复键的每一
// 次出现，因此 {"command":"set ...","command":null} 与先 null 后字符串能被
// 正确区分；只改变大小写的写法（Command、COMMAND 等）同样参与判断。
func lastCommandIsNull(data []byte) bool {
	dec := json.NewDecoder(bytes.NewReader(data))
	tok, err := dec.Token()
	if err != nil || tok != json.Delim('{') {
		return false
	}
	var lastRaw json.RawMessage
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return false
		}
		key, ok := keyTok.(string)
		if !ok {
			return false
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return false
		}
		if strings.EqualFold(key, "command") {
			// Decode 复用并可能覆盖传入切片，逐次拷贝保留本次字面量。
			lastRaw = append(json.RawMessage(nil), raw...)
		}
	}
	if lastRaw == nil {
		return false
	}
	trimmed := bytes.TrimSpace(lastRaw)
	return bytes.Equal(trimmed, jsonNullLiteral)
}

// rejectNonStringCommand 扫描一个日志条目对象，确认每一次 command 出现的值都
// 是字符串或 null；只要有一次为数字、布尔、对象或数组，就返回与普通类型化解
// 码完全相同的 *json.UnmarshalTypeError（Field 为 command、Type 为 string）。
// 它只在“最后一次 command 为 null”时需要：此时整体形状解码会因最后的 null
// 跳过字符串类型校验，无法替我们拦住前面出现的非法类型。错误交由外层解码附
// 加上下文后，呈现为 ...entries.command / ...log.command of type string。
func rejectNonStringCommand(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	tok, err := dec.Token()
	if err != nil || tok != json.Delim('{') {
		return nil
	}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return nil
		}
		if !strings.EqualFold(key, "command") {
			continue
		}
		trimmed := bytes.TrimSpace(raw)
		if bytes.Equal(trimmed, jsonNullLiteral) || len(trimmed) > 0 && trimmed[0] == '"' {
			continue
		}
		// 与 literalStore 对非字符串值的描述保持一致。
		value := "number"
		switch trimmed[0] {
		case 't', 'f':
			value = "bool"
		case '{':
			value = "object"
		case '[':
			value = "array"
		}
		return &json.UnmarshalTypeError{Value: value, Type: reflect.TypeOf(""), Field: "command"}
	}
	return nil
}

var jsonNullLiteral = []byte("null")

// normalizeEntryJSONError 把条目形状解码产出的类型错误整理回库类型的稳定文本：
// 错误来自局部 entryUnmarshalShape 时，encoding/json 会把这个匿名实现细节写进
// Struct 与“整条条目不是对象”的 Type；这里把整条条目级别的 Type 改回
// mevwatch.LogEntry，字段级（index/term/command）错误保持原样，由外层解码附
// 加 requests.entries / log 的字段路径。非类型错误原样返回。
func normalizeEntryJSONError(err error) error {
	var te *json.UnmarshalTypeError
	if !errors.As(err, &te) {
		return err
	}
	fixed := *te
	if fixed.Type == reflect.TypeOf(entryUnmarshalShape{}) {
		fixed.Type = reflect.TypeOf(mevwatch.LogEntry{})
	}
	return &fixed
}

// unmarshalLastWinsEntryArray 把一次数组字段出现解进一份全新的条目切片，并在
// 转换为库类型后整体替换 dst。它必须先解进局部切片而不能直接解到 dst，原因与
// unmarshalLastWinsArray 相同：encoding/json 对“非 nil 现有切片 + 重复数组键”
// 只做下标覆盖，短数组的尾部与元素内省略的字段都会残留上一次出现的内容。null
// 与既有行为一致，把目标置为空切片（nil）。
func unmarshalLastWinsEntryArray(data []byte, dst *[]mevwatch.LogEntry) error {
	var next []replicateInputEntry
	if err := json.Unmarshal(data, &next); err != nil {
		return err
	}
	entries := make([]mevwatch.LogEntry, len(next))
	for i := range next {
		entries[i] = mevwatch.LogEntry(next[i])
	}
	*dst = entries
	return nil
}

