	input := `{"currentTerm":1,"applyKV":true,"requests":[
	  {"term":1,"prevLogIndex":0,"prevLogTerm":0,"leaderCommit":0,
	   "entries":[{"index":1,"term":1,"command":"set count=7","command":null}]}
	]}`
