131	func normalizeRequestJSONError(err error) error {
132		var te *json.UnmarshalTypeError
133		if !errors.As(err, &te) {
134			return err
135		}
136		fixed := *te
137		fixed.Field = strings.TrimPrefix(fixed.Field, "AppendRequest.")
138		if fixed.Type == reflect.TypeOf(requestUnmarshalShape{}) {
139			fixed.Type = reflect.TypeOf(replicateInputRequest{})
140		}
141		return &fixed
142	}
143	
144	// replicateInputEntry 是读取阶段的日志条目：以库类型 mevwatch.LogEntry 为底层
145	// 类型另行定义，只为挂载输入特有的 command 解码规则。读完后整个值可直接转换回
146	// mevwatch.LogEntry，无须逐字段搬运。
147	type replicateInputEntry mevwatch.LogEntry
148	
149	// entryUnmarshalShape 是“最后一次 command 不是 null”时的解码形状：command 解
150	// 在普通字符串字段上。这样 encoding/json 会拒绝每一次数字/布尔/对象/数组出现
151	// （saveError 保留首个类型错误，后面的合法字符串盖不掉），字符串重复出现时取
152	// 最后一次，null 出现在非最后位置时被忽略、随后的字符串照常生效。它只是
153	// UnmarshalJSON 内的局部形状，不构成第二套条目字段；其类型名不会出现在整理后
154	// 的错误信息里（见 normalizeEntryJSONError）。
155	type entryUnmarshalShape struct {
156		Index   int    `json:"index"`
157		Term    int    `json:"term"`
158		Command string `json:"command"`
159	}
160	
161	// entryFieldsShape 只取 index/term，用于“最后一次 command 为 null”的分支：
162	// 该分支的 command 固定为空串，不能再解进字符串字段（否则先字符串后 null 会
163	// 留下前面的字符串）；每一次 command 出现是否合法由 rejectNonStringCommand
164	// 单独保证。
165	type entryFieldsShape struct {
166		Index int `json:"index"`
167		Term  int `json:"term"`
168	}
169	
170	// UnmarshalJSON 解码一个日志条目，并对 command 施加“同一对象内可重复、最后
171	// 一次出现决定内容”的规则：
172	//
173	//   - 任一次出现（含只改变字段名大小写的写法）为数字、布尔、对象或数组时，
174	//     都是输入类型错误；后面的合法字符串不能掩盖这次错误。整份输入按既有
175	//     JSON 类型错误拒绝（退出码 1、标准错误保留 replicate: 前缀）。
176	//   - 最后一次出现是字符串时按原文保留；是 null 时为空字符串，与单独给出
177	//     command:null 或省略 command 的结果一致；先 null 后字符串时采用后面的
178	//     字符串。
179	//
180	// 先用 token 扫描判断最后一次 command 是否为 null（扫描保留重复键的每一次
181	// 出现，map 解码只会留下最后一次，无法区分先后）：不是 null 时走普通字符串
182	// 解码，由 encoding/json 既有的“首个类型错误保留”行为拦住每一次非法类型并
183	// 给出最后一个字符串；是 null 时 command 固定为空串，只解 index/term，并额外
184	// 确认每一次 command 出现都只能是字符串或 null（最后的 null 会让普通字符串
185	// 解码跳过类型校验，拦不住前面出现的数字等非法类型）。
186	func (e *replicateInputEntry) UnmarshalJSON(data []byte) error {
187		if !lastCommandIsNull(data) {
188			var shape entryUnmarshalShape
189			if err := json.Unmarshal(data, &shape); err != nil {
190				return normalizeEntryJSONError(err)
191			}
192			*e = replicateInputEntry{Index: shape.Index, Term: shape.Term, Command: shape.Command}
193			return nil
194		}
195	
196		var fields entryFieldsShape
197		if err := json.Unmarshal(data, &fields); err != nil {
198			return normalizeEntryJSONError(err)
199		}
200		if err := rejectNonStringCommand(data); err != nil {
201			return err
202		}
203		*e = replicateInputEntry{Index: fields.Index, Term: fields.Term, Command: ""}
204		return nil
205	}
206	
207	// lastCommandIsNull 扫描一个日志条目对象的 token 流，报告按输入顺序最后一次
208	// 出现的 command（键名大小写不敏感，与 encoding/json 的字段识别一致）是否为
209	// null。没有 command 出现、条目不是对象或 JSON 无法解析时返回 false——这些
