// （saveError 保留首个类型错误，后面的合法字符串盖不掉），字符串重复出现时取
// 最后一次，null 出现在非最后位置时被忽略、随后的字符串照常生效。它只是
// UnmarshalJSON 内的局部形状，不构成第二套条目字段；其类型名不会出现在整理后
// 的错误信息里（见 normalizeEntryJSONError）。
type entryUnmarshalShape struct {
	Index   int    `json:"index"`
	Term    int    `json:"term"`
	Command string `json:"command"`
}

// entryFieldsShape 只取 index/term，用于“最后一次 command 为 null”的分支：
// 该分支的 command 固定为空串，不能再解进字符串字段（否则先字符串后 null 会
// 留下前面的字符串）；每一次 command 出现是否合法由 rejectNonStringCommand
// 单独保证。
type entryFieldsShape struct {
	Index int `json:"index"`
	Term  int `json:"term"`
}

// UnmarshalJSON 解码一个日志条目，并对 command 施加“同一对象内可重复、最后
// 一次出现决定内容”的规则：
//
//   - 任一次出现（含只改变字段名大小写的写法）为数字、布尔、对象或数组时，
//     都是输入类型错误；后面的合法字符串不能掩盖这次错误。整份输入按既有
//     JSON 类型错误拒绝（退出码 1、标准错误保留 replicate: 前缀）。
//   - 最后一次出现是字符串时按原文保留；是 null 时为空字符串，与单独给出
//     command:null 或省略 command 的结果一致；先 null 后字符串时采用后面的
//     字符串。
//
// 先用 token 扫描判断最后一次 command 是否为 null（扫描保留重复键的每一次
// 出现，map 解码只会留下最后一次，无法区分先后）：不是 null 时走普通字符串
// 解码，由 encoding/json 既有的“首个类型错误保留”行为拦住每一次非法类型并
// 给出最后一个字符串；是 null 时 command 固定为空串，只解 index/term，并额外
// 确认每一次 command 出现都只能是字符串或 null（最后的 null 会让普通字符串
// 解码跳过类型校验，拦不住前面出现的数字等非法类型）。
func (e *replicateInputEntry) UnmarshalJSON(data []byte) error {
	if !lastCommandIsNull(data) {
		var shape entryUnmarshalShape
		if err := json.Unmarshal(data, &shape); err != nil {
			return normalizeEntryJSONError(err)
		}
		*e = replicateInputEntry{Index: shape.Index, Term: shape.Term, Command: shape.Command}
		return nil
	}

	var fields entryFieldsShape
	if err := json.Unmarshal(data, &fields); err != nil {
		return normalizeEntryJSONError(err)
	}
	if err := rejectNonStringCommand(data); err != nil {
		return err
	}
	*e = replicateInputEntry{Index: fields.Index, Term: fields.Term, Command: ""}
	return nil
}

// lastCommandIsNull 扫描一个日志条目对象的 token 流，报告按输入顺序最后一次
// 出现的 command（键名大小写不敏感，与 encoding/json 的字段识别一致）是否为
// null。没有 command 出现、条目不是对象或 JSON 无法解析时返回 false——这些
// 情况交给随后的普通类型化解码产出既有结果或错误。token 流保留重复键的每一
// 次出现，因此 {"command":"set ...","command":null} 与先 null 后字符串能被
// 正确区分；只改变大小写的写法（Command、COMMAND 等）同样参与判断。
func lastCommandIsNull(data []byte) bool {
	dec := json.NewDecoder(bytes.NewReader(data))
	tok, err := dec.Token()
	if err != nil || tok != json.Delim('{') {
		return false
	}
	var lastRaw json.RawMessage
	found := false
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return false
		}
		key, ok := keyTok.(string)
		if !ok {
			return false
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return false
		}
		if strings.EqualFold(key, "command") {
			// Decode 复用并可能覆盖传入切片，逐次拷贝保留本次字面量。
			lastRaw = append(json.RawMessage(nil), raw...)
			found = true
		}
	}
	if !found {
		return false
	}
	return bytes.Equal(bytes.TrimSpace(lastRaw), jsonNullLiteral)
}

// rejectNonStringCommand 扫描一个日志条目对象，确认每一次 command 出现的值都
// 是字符串或 null；只要有一次为数字、布尔、对象或数组，就返回与普通类型化解
// 码同形的 *json.UnmarshalTypeError（Field 为 command、Type 为 string）。它只
// 在“最后一次 command 为 null”时需要：此时普通字符串解码会因最后的 null 跳过
// 类型校验，拦不住前面出现的非法类型。错误交由外层解码附加上下文后，呈现为
// ...entries.command / ...log.command of type string。
func rejectNonStringCommand(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	tok, err := dec.Token()
	if err != nil || tok != json.Delim('{') {
		return nil
	}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return nil
		}
		if !strings.EqualFold(key, "command") {
			continue
		}
		trimmed := bytes.TrimSpace(raw)
		if bytes.Equal(trimmed, jsonNullLiteral) || len(trimmed) > 0 && trimmed[0] == '"' {
			continue
		}
		// 与 literalStore 对非字符串标量/容器的描述保持一致。
		value := "number"
		if len(trimmed) > 0 {
			switch trimmed[0] {
			case 't', 'f':
				value = "bool"
			case '{':
				value = "object"
			case '[':
				value = "array"
			}
		}
		return &json.UnmarshalTypeError{Value: value, Type: reflect.TypeOf(""), Field: "command"}
	}
	return nil
}

var jsonNullLiteral = []byte("null")

// normalizeEntryJSONError 把条目形状解码产出的类型错误整理回库类型的稳定文本：
// “整条条目不是对象”的错误来自局部 entryUnmarshalShape/entryFieldsShape，
// encoding/json 会把这个实现细节写进 Type；这里改回 mevwatch.LogEntry。字段级
// （index/term）错误的 Type 本就是 int，保持原样，由外层解码补上
// requests.entries / log 的字段路径。非类型错误原样返回。
func normalizeEntryJSONError(err error) error {
	var te *json.UnmarshalTypeError
	if !errors.As(err, &te) {
		return err
	}
	fixed := *te
	switch fixed.Type {
	case reflect.TypeOf(entryUnmarshalShape{}), reflect.TypeOf(entryFieldsShape{}):
		fixed.Type = reflect.TypeOf(mevwatch.LogEntry{})
	}
	return &fixed
}

